"""Generate the full agent context from the authoritative contract and public exports.

Purpose: Keep the committed full context synchronized with its sources. Scope: Read docs/llms.txt and the package and
public subpackage __all__ exports. Usage: Run python .github/scripts/generate_llms_full.py, optionally with --check.
Outputs: Write docs/llms-full.txt, or report drift without changing it. Failure: Return 1 for drift; source, import and
filesystem errors propagate. Used by: Maintainers, the llms-full-sync hook and documentation integration tests.

Only the standard library and this checkout's dependency-free package are needed. Constants have no symbol docstring;
inherited value-type documentation is omitted because it describes the type rather than the export and varies across
Python versions.

"""

import argparse
import inspect
import sys
from enum import Enum
from importlib import import_module
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / "docs" / "llms.txt"
OUTPUT = ROOT / "docs" / "llms-full.txt"
# The package root plus its public subpackages. Flat public modules (`deprecation`, `messaging`, `module`,
# `routine`, `utils`) are left out: the root re-exports their user-facing names.
PUBLIC_MODULES = ("deprecate", "deprecate.audit", "deprecate.docstring", "deprecate.proxy")
REGENERATE = "python .github/scripts/generate_llms_full.py"

# A language: python hook has no project installation; always inspect this checkout.
sys.path.insert(0, str(ROOT / "src"))


def _describe(value: object) -> tuple[str, str]:
    """Return an export's kind and first docstring line, unwrapping class aliases."""
    original = inspect.unwrap(value) if callable(value) else value
    if inspect.isclass(original):
        kind = "enum" if issubclass(original, Enum) else "class"
    elif inspect.isroutine(original):
        kind = "function"
    else:
        return "constant", "No symbol docstring."
    doc = inspect.getdoc(original) or "No docstring."
    return kind, doc.splitlines()[0]


def render() -> str:
    """Render the authoritative contract followed by a sorted public API map.

    Returns:
        The complete generated file, including its regeneration header.

    """
    # Text mode folds CRLF from a Windows checkout to LF, so the render does not depend on git's eol setting.
    source = SOURCE.read_text(encoding="utf-8")
    header = f"<!-- Generated by .github/scripts/generate_llms_full.py; regenerate: {REGENERATE} -->\n\n"
    lines = ["## API Map", ""]
    for module_name in sorted(PUBLIC_MODULES):
        module = import_module(module_name)
        lines.extend([f"### {module_name}", ""])
        for name in sorted(module.__all__):
            kind, summary = _describe(getattr(module, name))
            lines.append(f"- `{module_name}.{name}` ({kind}): {summary}")
        if not module.__all__:
            lines.append("No public exports.")
        lines.append("")
    separator = "\n" if source.endswith("\n") else "\n\n"
    return header + source + separator + "\n".join(lines)


def main() -> int:
    """Write the generated file or check it for drift and return an exit code."""
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--check", action="store_true", help="Report drift without writing the file.")
    args = parser.parse_args()
    expected = render()
    if args.check:
        if not OUTPUT.is_file() or OUTPUT.read_text(encoding="utf-8") != expected:
            print(f"docs/llms-full.txt is out of date; run: {REGENERATE}", file=sys.stderr)
            return 1
        return 0
    # Byte writes keep LF line endings on Windows too.
    OUTPUT.write_bytes(expected.encode("utf-8"))
    return 0


if __name__ == "__main__":
    sys.exit(main())
